"use strict";
function qSig8(q) {
  if (!q) return "?";
  var s = (q.prompt || "") + "|";
  try {
    if (q.visual) s += String(q.visual).replace(/<[^>]+>/g, " ");
    if (q.pairs) s += q.pairs.map(function (p) { return (p.l || p.a || "") + "=" + (p.r || p.b || ""); }).join(";");
    if (q.items) s += q.items.map(function (it) { return it.html || ""; }).join(";");
    if (q.rounds) s += q.rounds.map(function (r) { return String(r.visual || "").replace(/<[^>]+>/g, " "); }).join(";");
  } catch (e) {}
  s = s.replace(/Đáp án:\s*\?/g, "");
  return s.replace(/\s+/g, " ").trim().slice(0, 140);
}
function factGen8(facts) { return function () { return factMCQ(pick(facts)); }; }
function factBlankGen8(facts) { return function () { return factBlank(pick(facts)); }; }
function sup8(n) { return String(n).replace(/-/g, "⁻").replace(/0/g, "⁰").replace(/1/g, "¹").replace(/2/g, "²").replace(/3/g, "³").replace(/4/g, "⁴").replace(/5/g, "⁵").replace(/6/g, "⁶").replace(/7/g, "⁷").replace(/8/g, "⁸").replace(/9/g, "⁹"); }
function mono8(a, m, n) { var s = (a === 1 ? "" : a) + "x" + (m > 1 ? sup8(m) : m === 1 ? "" : "⁰"); if (n > 0) s += "y" + (n > 1 ? sup8(n) : ""); if (m === 0) s = (a === 1 ? "" : a) + (n > 0 ? "y" + (n > 1 ? sup8(n) : "") : ""); return s; }

