function kh8CMol() { var v = pick([1, 2, 4, 5]), n = rand(1, 6); return numMCQ6("Dung dịch chứa " + (n * v) + " mol chất tan trong " + v + " lít dung dịch. Nồng độ mol là bao nhiêu mol/l?", "CM = ?", n, "CM = n : V = " + (n * v) + " : " + v + " = " + n + " mol/l.", 2); }
function kh8BTKL() { var a = rand(3, 15), b = rand(3, 15), d = rand(2, a + b - 2); var c = a + b - d; return numMCQ6("Phản ứng: A + B → C + D. Biết mA = " + a + " g, mB = " + b + " g, mD = " + d + " g. Khối lượng chất C tạo thành là bao nhiêu gam?", "mC = ?", c, "Định luật bảo toàn khối lượng: mC = mA + mB − mD = " + a + " + " + b + " − " + d + " = " + c + " g.", 4); }
function kh8Density() { var v = pick([2, 4, 5, 10, 20]), dPick = pick([1, 2, 3, 5, 8]); return numMCQ6("Một vật có thể tích " + v + " cm³ và khối lượng riêng " + dPick + " g/cm³. Khối lượng của vật là bao nhiêu gam?", "m = ?", v * dPick, "m = D × V = " + dPick + " × " + v + " = " + (v * dPick) + " g.", 10); }
function kh8Pressure() { var s = pick([2, 4, 5, 10]), f = rand(2, 12) * s; return numMCQ6("Tác dụng một lực " + f + " N lên diện tích bị ép " + s + " m². Áp suất là bao nhiêu Pa?", "p = ?", f / s, "p = F : S = " + f + " : " + s + " = " + (f / s) + " Pa.", 5); }
function kh8LiquidP() { var h = rand(1, 6); return numMCQ6("Cột nước có trọng lượng riêng d = 10 000 N/m³. Áp suất của nước tại độ sâu " + h + " m là bao nhiêu Pa?", "p = ?", 10000 * h, "p = d × h = 10 000 × " + h + " = " + fmtN(10000 * h) + " Pa.", 8000); }
function kh8Arch() { var v = pick([1, 2, 3, 4, 5]); return numMCQ6("Một vật chìm hoàn toàn trong nước, chiếm thể tích " + v + " dm³ (0,00" + v + " m³). Lực đẩy Archimedes của nước (d = 10 000 N/m³) tác dụng lên vật là bao nhiêu N?", "FA = ?", v * 10, "FA = d × V = 10 000 × 0,00" + v + " = " + (v * 10) + " N.", 6); }
function kh8Moment() { var d = pick([1, 2, 3, 4]), f = rand(3, 20); return numMCQ6("Một lực " + f + " N tác dụng cách trục quay " + d + " m. Moment của lực là bao nhiêu N·m?", "M = ?", f * d, "M = F × d = " + f + " × " + d + " = " + (f * d) + " N·m.", 8); }
function kh8Lever() { var d1 = pick([1, 2, 3]), d2 = pick([1, 2, 3]), f2 = rand(3, 15); var f1 = f2 * d2 / d1; while (f1 !== Math.floor(f1)) { f2 += 1; f1 = f2 * d2 / d1; } return numMCQ6("Đòn bẩy cân bằng: lực F₂ = " + f2 + " N tác dụng cách điểm tựa " + d2 + " m, lực F₁ tác dụng cách điểm tựa " + d1 + " m. F₁ bằng bao nhiêu N?", "F₁ = ?", f1, "Điều kiện cân bằng của đòn bẩy: F₁ × " + d1 + " = F₂ × " + d2 + " = " + (f2 * d2) + " → F₁ = " + f1 + " N.", 5); }
